import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as r,ag as a}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const p=JSON.parse('{"title":"Cindy 学习地图","description":"Cindy 是开源的桌面加手机 AI 智能体应用，把 Claude Code、Codex、Pi 三个 harness 装进同一个工作区，让任务、模型和技能跨设备可用。本页是产品全景加决策表：先回答「我要做什么、该不该用它」，再进教程和源码解读。","frontmatter":{"title":"Cindy 学习地图","description":"Cindy 是开源的桌面加手机 AI 智能体应用，把 Claude Code、Codex、Pi 三个 harness 装进同一个工作区，让任务、模型和技能跨设备可用。本页是产品全景加决策表：先回答「我要做什么、该不该用它」，再进教程和源码解读。","domain":"product","tags":["multi-agent","coding-agent","device-link"],"role":"map"},"headers":[],"relativePath":"zh/products/cindy/index.md","filePath":"zh/products/cindy/index.md","lastUpdated":1795592559000}'),n={name:"zh/products/cindy/index.md"};function i(o,t,l,c,h,s){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="cindy-学习地图" tabindex="-1">Cindy 学习地图 <a class="header-anchor" href="#cindy-学习地图" aria-label="Permalink to &quot;Cindy 学习地图&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> Cindy 是心动（XD）运营的开源 AI 智能体应用，服务的是已经在用 Claude Code 或 Codex 的人： 把三个 agent 引擎装进同一个工作区，让同一个任务、同一份记忆在多个引擎和多台设备之间延续。 <strong>想在一台设备上把几个编码 agent 放在一起用，或者在手机上接着电脑上的活，就看本目录。</strong> 只用一个 agent、也不需要多设备，直接用原工具更省事。</p></blockquote><h2 id="写给谁、先决条件与非目标" tabindex="-1">写给谁、先决条件与非目标 <a class="header-anchor" href="#写给谁、先决条件与非目标" aria-label="Permalink to &quot;写给谁、先决条件与非目标&quot;">​</a></h2><ul><li><strong>写给谁</strong>：已经在用或准备用 Claude Code、Codex 的前端工程师，想知道要不要装 Cindy、和手上的工具是什么关系。</li><li><strong>先决条件</strong>：知道「agent 能读文件、跑命令」这个程度即可。术语在<a href="./cindy.html">教程</a>里第一次出现时都会解释。</li><li><strong>非目标</strong>： <ul><li>不教 Claude Code、Codex、Pi 本身，见 <a href="./../claude/">Claude</a>、<a href="./../codex/">Codex</a>、<a href="./../pi-coding-agent.html">Pi</a>。</li><li>不教自建 Cindy 后端。README 写明「服务端不在本仓库」。</li><li>不覆盖团队版与企业版的采购细节，两者尚未开放。</li></ul></li></ul><h2 id="产品家族" tabindex="-1">产品家族 <a class="header-anchor" href="#产品家族" aria-label="Permalink to &quot;产品家族&quot;">​</a></h2><p>下表的「官方名称」抄自 2026-11-24 打开的官网、README 与仓库文档。带「应用内」的项没有独立官网页面。</p><table tabindex="0"><thead><tr><th>官方名称</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td>Cindy（开源客户端，Apache-2.0）</td><td><a href="https://cindy.app" target="_blank" rel="noreferrer">cindy.app</a> · <a href="https://cindy.cn" target="_blank" rel="noreferrer">cindy.cn</a> · <a href="https://github.com/makecindy/cindy/releases" target="_blank" rel="noreferrer">GitHub</a></td><td>本目录：<a href="./cindy.html">教程</a>、<a href="./source.html">源码解读</a></td></tr><tr><td>中国大陆版 / 国际版</td><td><a href="https://cindy.cn/download" target="_blank" rel="noreferrer">cindy.cn/download</a> · <a href="https://cindy.app/download" target="_blank" rel="noreferrer">cindy.app/download</a></td><td><a href="./cindy.html">教程的安装一节</a></td></tr><tr><td>Cindy 官方模型服务（界面里叫 Cindy AI）</td><td><a href="https://cindy.cn/pricing" target="_blank" rel="noreferrer">中国大陆定价</a> · <a href="https://cindy.app/pricing" target="_blank" rel="noreferrer">国际版定价</a></td><td>教程「计费」一节</td></tr><tr><td>移动端（iOS、iPadOS、Android）</td><td>下载页</td><td>教程「连接第二台电脑和手机」</td></tr><tr><td>Linux 桌面端</td><td>国际版下载页 · <a href="https://github.com/makecindy/cindy/blob/6fdec7fb89b955be548c3f5cc9a42d83bf174aa3/docs/linux.md" target="_blank" rel="noreferrer">安装指南</a></td><td>教程「安装」</td></tr><tr><td>Device Link</td><td>应用内</td><td>教程「连接第二台电脑和手机」；源码解读</td></tr><tr><td>远程桌面</td><td>应用内（手机端）</td><td>教程「连接第二台电脑和手机」</td></tr><tr><td>Agent-Net (Beta)</td><td>应用内开关，默认关</td><td>源码解读</td></tr><tr><td>伙伴（companion）</td><td>应用内</td><td>教程「建一个伙伴」</td></tr><tr><td>自动化（automation）</td><td>应用内</td><td>教程「设自动化」</td></tr><tr><td>聊天渠道（Slack、Telegram、飞书等）</td><td>应用内</td><td>教程「接聊天渠道」</td></tr><tr><td>Orca（协同）</td><td>应用内</td><td>教程「用 Orca 让多个 agent 分工」；源码解读</td></tr><tr><td>SkillHub</td><td>应用内</td><td>教程「用记忆和 Skill」</td></tr><tr><td>官方插件仓库 cindy-official-plugins</td><td><a href="https://github.com/makecindy/cindy-official-plugins" target="_blank" rel="noreferrer">GitHub</a></td><td>地图一行：官方插件的源码与上架流程</td></tr><tr><td>插件版引擎（cindy-dsh-plugin、cindy-antigravity-plugin、cindy-zcode-plugin）</td><td><a href="https://github.com/makecindy" target="_blank" rel="noreferrer">GitHub 组织</a></td><td>地图一行：把 DeepSeek Harness、Antigravity CLI、ZCode 作为引擎接入的插件</td></tr><tr><td>Cindy Host（<code>cindy-host</code>）</td><td>无公开页；见仓库 <code>docs/host/README.md</code></td><td>源码解读；实验性</td></tr><tr><td>Cindy Headless</td><td>无公开页；见仓库 <code>apps/cindy-headless/README.md</code></td><td>源码解读；面向容器与评测</td></tr><tr><td>团队与企业版（Team &amp; Enterprise）</td><td>官网首页「候补名单」</td><td>地图一行：状态是「即将上线」「联系我们」</td></tr><tr><td>隐私政策、服务条款</td><td><a href="https://cindy.cn/privacy" target="_blank" rel="noreferrer">cindy.cn/privacy</a> · <a href="https://cindy.app/privacy" target="_blank" rel="noreferrer">cindy.app/privacy</a> · <a href="https://cindy.cn/terms" target="_blank" rel="noreferrer">cindy.cn/terms</a></td><td>教程「安全与隐私要点」</td></tr></tbody></table><h3 id="容易撞名与误解" tabindex="-1">容易撞名与误解 <a class="header-anchor" href="#容易撞名与误解" aria-label="Permalink to &quot;容易撞名与误解&quot;">​</a></h3><ul><li><strong>Cindy 要认准出处。</strong> 仓库在 <code>makecindy</code> 组织下，官网只有 <code>cindy.app</code> 和 <code>cindy.cn</code> 两个。</li><li><strong>中国大陆版不等于国际版。</strong> 两个官网、两套账号。README 提醒开发时「中国大陆账号必须使用 <code>cn</code>，国际版账号必须使用 <code>global</code>」。</li><li><strong>harness 不等于模型。</strong> harness 是执行引擎（Claude Code、Codex、Pi），模型是另一层选择。</li><li><strong>Pi 是 harness，不是订阅。</strong> 官网原话：「Pi 是 Harness，无需另买一份订阅。」</li><li><strong>界面里的「任务」就是 session。</strong> 官方文档里任务、session、task 混用，指同一个东西。</li><li><strong>Device Link 不等于 Agent-Net。</strong> 前者是现有的设备互联，后者是标了 Beta 的新版，默认关闭。</li><li><strong>伙伴不等于子代理。</strong> 伙伴是跨任务存在的角色；子代理是某个 agent 内部一次性的子任务执行者。</li><li><strong>Skill 不等于插件。</strong> Skill 是一份操作说明；插件是 <code>.cindy</code> 安装包，能带界面和新工具。</li><li><strong>「跳过登录」不等于自建服务端。</strong> 它只是不登录 Cindy 账号，客户端仍然连着官方云服务的地址。</li><li><strong>源码里有一批旧名字。</strong> 仓库内部把产品叫 <code>xdt-maker</code>，把插件叫 Ghost，把协同叫 Orca，环境变量前缀是 <code>XDT_</code>。搜代码时要按这些名字搜。</li><li><strong><code>cindy-host</code> 与 <code>cindy-headless</code> 是两个东西。</strong> 前者是 <code>apps/host</code> 里的通用后台服务，后者是 <code>apps/cindy-headless</code> 里面向容器和评测的运行时。</li><li><strong>版本号容易看反。</strong> GitHub 上最早的 Release 叫 <code>v1.0.0</code>（2026-07-25），之后发布的版本号却是 <code>v0.1.x</code>。<code>v1.0.0</code> 没有附带任何安装包，说明写它「标记 1.0.0 版本期的开源客户端源码快照」；截至 2026-11-24，最新的正式版是 <code>v0.1.144</code>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>README 对问题的描述只有一句话：「连接你的多台电脑与手机，把熟悉的 Agent、模型和已有订阅放在一起」。 落到日常，是下面这些反复出现的不顺手：</p><table tabindex="0"><thead><tr><th>场景</th><th>没有 Cindy</th><th>有 Cindy</th></tr></thead><tbody><tr><td>同时用 Claude Code 和 Codex</td><td>换一个 agent 就要从头交代背景</td><td>同一个任务里换 harness 接着干，Cindy 用交接文本把上下文带过去</td></tr><tr><td>人离开电脑</td><td>活停在电脑上</td><td>手机或另一台电脑打开同一个任务，继续对话、访问文件</td></tr><tr><td>聊天搞不定，要亲手点软件</td><td>只能回到电脑前</td><td>手机端内置远程桌面</td></tr><tr><td>一台电脑上配好的模型</td><td>别的设备要再配一遍</td><td>开启远程调用后，其他设备可以借用</td></tr><tr><td>积累的工作方法</td><td>散落在各个工具自己的配置里</td><td>记忆、Skill、伙伴由 Cindy 统一管理，跨引擎共享</td></tr><tr><td>重复的事</td><td>每次手动发起</td><td>设成自动化，或在聊天渠道里 @ 一句</td></tr><tr><td>一个 agent 忙不过来</td><td>手动在几个工具之间搬结果</td><td>Orca：一个 Lead 带多个 Worker，各选 harness 和模型</td></tr></tbody></table><p>有一件事它<strong>不</strong>做，官网常见问题写得很清楚：电脑关机后，手机不能让任务继续跑。 远程任务由电脑执行，手机「不会把离线电脑的工作自动搬到云端执行」。</p><h3 id="与替代方案对比" tabindex="-1">与替代方案对比 <a class="header-anchor" href="#与替代方案对比" aria-label="Permalink to &quot;与替代方案对比&quot;">​</a></h3><p>下表只写 Cindy 这一侧能核实的事实，其他产品的细节以各自页面为准。</p><table tabindex="0"><thead><tr><th>工具</th><th>它管什么</th><th>和 Cindy 的关系</th><th>适合谁</th></tr></thead><tbody><tr><td>Claude Code、Codex、Pi</td><td>各自是一个 harness</td><td>Cindy 把三者装进来，不替代它们</td><td>只用一个 harness、不需要多设备的人，直接用原工具</td></tr><tr><td><a href="./../t3code/">T3 Code</a></td><td>同类的多 agent 工作区</td><td>定位相近，选型时要逐项对比</td><td>在两者之间做选型的人</td></tr><tr><td><a href="./../tailscale/">Tailscale</a>、<a href="./../uu-remote/">UU Remote</a></td><td>远程控制与组网</td><td>Cindy 的 Device Link 只连你账号下的 Cindy 设备，远程桌面只在手机端内置；它不是通用组网工具</td><td>需要连任意设备、任意服务的人</td></tr><tr><td><a href="./../codex/dot.html">Codex 云端智能体</a></td><td>任务在云端常驻运行</td><td>Cindy 让你自己的电脑当服务器，任务和文件留在本机，电脑得在线</td><td>不想维护一台常开电脑的人</td></tr><tr><td>自己搭服务器跑 agent</td><td>自己部署、自己维护</td><td>README 的说法是「不用另租服务器，也不必自己搭服务」</td><td>有自建需求、且能接受服务端不在开源范围的人</td></tr></tbody></table><h2 id="快速决策-我该不该用、从哪里开始" tabindex="-1">快速决策：我该不该用、从哪里开始 <a class="header-anchor" href="#快速决策-我该不该用、从哪里开始" aria-label="Permalink to &quot;快速决策：我该不该用、从哪里开始&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我的情况</th><th>用什么</th></tr></thead><tbody><tr><td>只用 Claude Code，只在一台电脑上</td><td>不需要 Cindy</td></tr><tr><td>同时用两个以上的编码 agent，来回复述背景很烦</td><td>用 Cindy，先读<a href="./cindy.html">教程</a>的「换 harness 接着干」</td></tr><tr><td>经常离开电脑，想在手机上看任务</td><td>用 Cindy 并登录，读「连接第二台电脑和手机」</td></tr><tr><td>想在手机上操作电脑上的软件</td><td>用 Cindy 的远程桌面；先确认电脑能保持在线</td></tr><tr><td>一台电脑配好了模型，别的设备想借用</td><td>用 Cindy 的模型共享，在那台电脑上允许远程调用</td></tr><tr><td>只想在一台电脑上用，不想让设备保持在线</td><td>用「跳过登录」的本地模式，自带 API key</td></tr><tr><td>不想自己配模型</td><td>登录后用 Cindy 官方模型服务，按量或包月付费</td></tr><tr><td>想让几个 agent 分头做一个大任务</td><td>用 Orca，每个 Worker 可以选不同的 harness</td></tr><tr><td>有一台常开的电脑，想让其他设备连回它</td><td>用 Cindy 并登录，电脑上打开「允许同账号设备控制本机」</td></tr><tr><td>每天有固定的巡检、汇报</td><td>用自动化，把结果推到聊天渠道</td></tr><tr><td>要审计代码、自己改</td><td>客户端是 Apache-2.0，读<a href="./source.html">源码解读</a></td></tr><tr><td>需要自建后端或私有部署</td><td>个人版不适用；企业版的 Gateway 自部署在官网上是「联系我们」</td></tr></tbody></table><h2 id="本目录怎么读" tabindex="-1">本目录怎么读 <a class="header-anchor" href="#本目录怎么读" aria-label="Permalink to &quot;本目录怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>读完能做什么</th><th>什么时候读</th></tr></thead><tbody><tr><td><a href="./cindy.html">教程</a></td><td>装好 Cindy，10 分钟跑通第一个任务，连上手机，设好隐私开关</td><td>第一次接触</td></tr><tr><td><a href="./source.html">源码解读</a></td><td>说清一次任务的数据流、Codex 接在哪里、手机控制电脑的边界、Orca 的实现</td><td>想审计代码、要贡献，或教程里「为什么这样」说不清的时候</td></tr></tbody></table><p>建议顺序：</p><ol><li><strong>先读教程，照着做完第一个任务。</strong> 没跑过就看源码，会被一堆名词挡住。</li><li><strong>再读教程的「安全与隐私要点」。</strong> 它决定你选登录还是跳过登录。</li><li><strong>最后按需读源码解读。</strong> 它回答的是「凭什么信它」，不解决「怎么用」。</li></ol><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://github.com/makecindy/cindy/blob/6fdec7fb89b955be548c3f5cc9a42d83bf174aa3/README.zh-CN.md" target="_blank" rel="noreferrer">仓库中文 README</a>：功能、两种运行模式、隐私与遥测的官方说明，事实的第一出处。</li><li><a href="https://cindy.cn" target="_blank" rel="noreferrer">官网</a>：定位、Harness 与模型的区别、常见问题。</li><li><a href="https://cindy.cn/download" target="_blank" rel="noreferrer">下载页</a>：各平台的系统要求。</li><li><a href="https://cindy.cn/pricing" target="_blank" rel="noreferrer">定价页</a>：四档价格、滚存规则与八条计费规则，截至 2026-11-24。</li><li><a href="https://cindy.cn/privacy" target="_blank" rel="noreferrer">隐私政策</a>：每一类数据的用途、心跳与使用统计、留存期限。</li><li><a href="https://cindy.cn/terms" target="_blank" rel="noreferrer">服务条款</a>：自备 key 模式与官方网关模式的责任边界。</li><li><a href="https://github.com/makecindy/cindy/releases" target="_blank" rel="noreferrer">GitHub Releases</a>：逐版本的更新说明。</li><li><a href="https://github.com/makecindy/cindy-official-plugins" target="_blank" rel="noreferrer">官方插件仓库</a>：官方插件的源码、审阅标准与自动上架流程。</li><li><a href="https://github.com/makecindy/cindy/blob/6fdec7fb89b955be548c3f5cc9a42d83bf174aa3/SUPPORT.md" target="_blank" rel="noreferrer">使用支持</a>：遇到问题先查哪里、怎么提 issue。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./cindy.html">教程</a>、<a href="./source.html">源码解读</a>：本目录的另外两页。</li><li><a href="./../claude/">Claude</a>、<a href="./../codex/">Codex</a>、<a href="./../pi-coding-agent.html">Pi</a>：Cindy 装进来的三个 harness。</li><li><a href="./../t3code/">T3 Code</a>：同类的多 agent 工作区。</li><li><a href="./../tailscale/">Tailscale</a>、<a href="./../uu-remote/">UU Remote</a>：远程控制与组网类工具。</li><li><a href="./../codex/dot.html">Codex 云端智能体</a>：任务在云端常驻运行的另一种思路。</li></ul>',26)])])}const u=d(n,[["render",i]]);export{p as __pageData,u as default};
